const purgeExpiredTrash = `-- name: PurgeExpiredTrash :execrows
DELETE FROM wiki_nodes n
WHERE n.trash_root_id IN (
    SELECT r.id FROM wiki_nodes r WHERE r.id = r.trash_root_id AND r.deleted_at < $1
)
`

func (q *Queries) PurgeExpiredTrash(ctx context.Context, deletedAt *time.Time) (int64, error) {
	result, err := q.db.Exec(ctx, purgeExpiredTrash, deletedAt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const purgeTrashRoot = `-- name: PurgeTrashRoot :exec
DELETE FROM wiki_nodes WHERE trash_root_id = $1
`

// Permanent removal of a trashed subtree; independently trashed descendants (other roots) survive.
func (q *Queries) PurgeTrashRoot(ctx context.Context, trashRootID uuid.NullUUID) error {
	_, err := q.db.Exec(ctx, purgeTrashRoot, trashRootID)
	return err
}

const rebaseDescendants = `-- name: RebaseDescendants :exec
UPDATE wiki_nodes
SET path = $1::text || substr(path, length($2::text) + 1),
    depth = depth + $3::smallint,
    space_id = $4
WHERE path LIKE $2::text || '%' AND id <> $5
`

type RebaseDescendantsParams struct {
	NewPrefix string
	OldPrefix string
	Delta     int16
	SpaceID   uuid.UUID
	ID        uuid.UUID
}

// Rewrites the descendants of a moved node: swaps the path prefix, shifts depth, follows the space.
func (q *Queries) RebaseDescendants(ctx context.Context, arg RebaseDescendantsParams) error {
	_, err := q.db.Exec(ctx, rebaseDescendants,
		arg.NewPrefix,
		arg.OldPrefix,
		arg.Delta,
		arg.SpaceID,
		arg.ID,
	)
	return err
}

